sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    current.setAbortAction(true);
    gs.addErrorMessage('TransformForge: target_table is required.');
})(current, previous);

sysauto_script.script:
// TransformForge — scheduled housekeeping
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runHousekeeping() {
    var RETENTION_DAYS = 90;
    var cutoff = new GlideDateTime();
    cutoff.addDaysUTC(-RETENTION_DAYS);

    var jobGr = new GlideRecord('x_sntf_transform_job');
    jobGr.addQuery('sys_created_on', '<', cutoff.getValue());
    jobGr.setLimit(1000);
    jobGr.query();
    var deleted = 0;
    while (jobGr.next()) {
        var jobId = jobGr.getUniqueValue();
        // Delete child mappings first.
        var mapGr = new GlideRecord('x_sntf_transform_mapping');
        mapGr.addQuery('job', jobId);
        mapGr.setLimit(1000);
        mapGr.query();
        while (mapGr.next()) {
            try { mapGr.setWorkflow(false); mapGr.deleteRecord(); } catch (e) { /* best effort */ }
        }
        try {
            jobGr.setWorkflow(false);
            jobGr.deleteRecord();
            deleted++;
        } catch (e) {
            gs.error('TransformForge housekeeping: delete failed for ' + jobId + ': ' + e.message);
        }
    }
    gs.info('TransformForge housekeeping: deleted ' + deleted + ' stale jobs');
})();
